//! Embedded wallet contract code and protocol constants.

/// Opcode prefix of a signed external message for wallet v5r1
/// (`prefix::signed_external` in `wallet_v5.fc`, ASCII "sign").
pub const V5R1_SIGNED_EXTERNAL_OPCODE: u32 = 0x7369_676E;

/// `action_send_msg#0ec3c86d` opcode of an `OutList` send action.
pub const ACTION_SEND_MSG_OPCODE: u32 = 0x0EC3_C86D;

/// Send-mode flag every externally-authorized v5r1 action must carry
/// (`IGNORE_ERRORS`; the contract rejects requests without it).
pub const SEND_MODE_IGNORE_ERRORS: u8 = 2;

/// Representation hash of the official wallet v4r2 code cell.
pub const WALLET_V4R2_CODE_HASH: [u8; 32] = [
    0xFE, 0xB5, 0xFF, 0x68, 0x20, 0xE2, 0xFF, 0x0D, 0x94, 0x83, 0xE7, 0xE0, 0xD6, 0x2C, 0x81, 0x7D,
    0x84, 0x67, 0x89, 0xFB, 0x4A, 0xE5, 0x80, 0xC8, 0x78, 0x86, 0x6D, 0x95, 0x9D, 0xAB, 0xD5, 0xC0,
];

/// Representation hash of the official wallet v5r1 (W5) code cell.
pub const WALLET_V5R1_CODE_HASH: [u8; 32] = [
    0x20, 0x83, 0x4B, 0x7B, 0x72, 0xB1, 0x12, 0x14, 0x7E, 0x1B, 0x2F, 0xB4, 0x57, 0xB8, 0x4E, 0x74,
    0xD1, 0xA3, 0x0F, 0x04, 0xF7, 0x37, 0xD4, 0xF6, 0x2A, 0x66, 0x8E, 0x95, 0x52, 0xD2, 0xB7, 0x2F,
];

/// Bag of Cells of the official wallet v4r2 code
/// (`ton-blockchain/wallet-contract`, compiled `wallet-v4-code.fc`; bytes as
/// shipped by `tonlib-core`'s `resources/wallet/wallet_v4r2.code`). Its root
/// cell hash is pinned by [`WALLET_V4R2_CODE_HASH`] and verified in tests.
pub const WALLET_V4R2_CODE_BOC: &str = "";

/// Bag of Cells of the official wallet v5r1 (W5) code
/// (`ton-blockchain/wallet-contract-v5`, compiled `wallet_v5.fc`; bytes as
/// shipped by `tonlib-core`'s `resources/wallet/wallet_v5.code`). Its root
/// cell hash is pinned by [`WALLET_V5R1_CODE_HASH`] and verified in tests.
pub const WALLET_V5R1_CODE_BOC: &str = "";
